create table revision_document (id bigint not null auto_increment, review_request_id bigint not null, document_id bigint not null, base_version_no int not null, draft_document_id bigint not null, proposed_body text not null, reexamine_round int not null default 0, result_version_no int, created_by bigint not null, created_at datetime(6) not null, updated_at datetime(6) not null, deleted_at datetime(6), primary key(id), constraint fk_revision_document_request foreign key(review_request_id) references review_request(id));
create table revision_dictionary (id bigint not null auto_increment, review_request_id bigint not null, dictionary_id bigint, base_version_no int not null, draft_dictionary_id bigint not null, reexamine_round int not null default 0, result_version_no int, created_by bigint not null, created_at datetime(6) not null, updated_at datetime(6) not null, deleted_at datetime(6), primary key(id), constraint fk_revision_dictionary_request foreign key(review_request_id) references review_request(id));
create index idx_revision_document_request on revision_document(review_request_id);
create index idx_revision_dictionary_request on revision_dictionary(review_request_id);
